"                           <button
                              key={tab.id}
                              onClick={() => {
                                 const mapping = {
                                    general: 'general',
                                    outlet: 'profile',
                                    printer: 'printers',
                                    shortcuts: 'shortcuts',
                                    formatting: 'formatting',
                                    profile: 'profile'
                                 };
                                 const permKey = mapping[tab.id];
                                 checkPermissionAndExecute('Settings', permKey, `${tab.label} Settings`, () => {
                                    setSettingsActiveTab(tab.id);
                                 });
                              }}"
